func (v SpecValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	arguments := types.ListValueMust(
		ArgumentsType{
			basetypes.ObjectType{
				AttrTypes: ArgumentsValue{}.AttributeTypes(ctx),
			},
		},
		v.Arguments.Elements(),
	)

	if v.Arguments.IsNull() {
		arguments = types.ListNull(
			ArgumentsType{
				basetypes.ObjectType{
					AttrTypes: ArgumentsValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	if v.Arguments.IsUnknown() {
		arguments = types.ListUnknown(
			ArgumentsType{
				basetypes.ObjectType{
					AttrTypes: ArgumentsValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	content := types.ListValueMust(
		ContentType{
			basetypes.ObjectType{
				AttrTypes: ContentValue{}.AttributeTypes(ctx),
			},
		},
		v.Content.Elements(),
	)

	if v.Content.IsNull() {
		content = types.ListNull(
			ContentType{
				basetypes.ObjectType{
					AttrTypes: ContentValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	if v.Content.IsUnknown() {
		content = types.ListUnknown(
			ContentType{
				basetypes.ObjectType{
					AttrTypes: ContentValue{}.AttributeTypes(ctx),
				},
			},
		)
	}

	attributeTypes := map[string]attr.Type{
		"arguments": basetypes.ListType{
			ElemType: ArgumentsValue{}.Type(ctx),
		},
		"content": basetypes.ListType{
			ElemType: ContentValue{}.Type(ctx),
		},
		"description": basetypes.StringType{},
		"title":       basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"arguments":   arguments,
			"content":     content,
			"description": v.Description,
			"title":       v.Title,
		})

	return objVal, diags
}

